'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),vm=require('node:vm'),fs=require('node:fs');
function load(files,extra={}){const c={window:null,...extra};c.window=c;vm.createContext(c);for(const file of files)vm.runInContext(fs.readFileSync(file,'utf8'),c,{filename:file});return c;}
const c=load(['white-orchard.js','progression-data.js','progression-engine.js','home-panel.js','home-metrics.js']);
const {tasks,hubs}=c.PHOENIX_ROUTE;for(const [id,q]of Object.entries(c.PHOENIX_PROGRESS_DATA.quests))if(!Number.isFinite(tasks[id].level))tasks[id].level=q.level;
const engine=c.createPhoenixProgress(c.PHOENIX_PROGRESS_DATA,tasks,hubs),panel=c.PhoenixHomePanel;
test('all 13 selectable quests have real objective totals and a valid view',()=>{const p=engine.init();for(const id of Object.keys(c.PHOENIX_PROGRESS_DATA.quests)){const v=panel.selectedQuestView(id,engine,p,tasks);assert.ok(v.counts.total>0);assert.ok(v.name);assert.equal(v.nextId,engine.required(id,p)[0].id);}});
test('objective completion advances without affecting optional totals',()=>{let p=engine.init();p=engine.plan(p,{}, {kind:'objective',id:'q-lilac:ghouls',value:true}).progress;const v=panel.selectedQuestView('q-lilac',engine,p,tasks);assert.equal(v.nextId,'q-lilac:ride');assert.equal(v.counts.done,1);});
test('legacy complete does not invent objective evidence',()=>{const p=engine.init({}, {'q-lilac':true});const v=panel.selectedQuestView('q-lilac',engine,p,tasks);assert.equal(v.status,'complete');assert.equal(v.legacy,true);assert.equal(v.counts.done,0);assert.equal(v.nextId,null);});
test('failed and departure-unavailable quests never offer next objective',()=>{const p=engine.init();p.failed['q-cargo']=true;assert.equal(panel.selectedQuestView('q-cargo',engine,p,tasks).nextId,null);p.manual.departed=true;assert.equal(panel.selectedQuestView('q-missing',engine,p,tasks).status,'unavailable');assert.equal(panel.selectedQuestView('q-missing',engine,p,tasks).nextId,null);});
test('selected branch skips closed objectives',()=>{let p=engine.init();p=engine.plan(p,{}, {kind:'objective',id:'q-firestarter:suspect',value:true},{choices:{arson:'bribe'}}).progress;const v=panel.selectedQuestView('q-firestarter',engine,p,tasks);assert.notEqual(v.nextId,'q-firestarter:fight');assert.equal(v.nextId,'q-firestarter:report');});
test('risk warnings use canonical risk list, never requirement keywords',()=>{const p=engine.init();assert.match(panel.selectedQuestView('q-missing',engine,p,tasks).warning,/Departure-sensitive/);assert.equal(panel.selectedQuestView('q-lilac',engine,p,tasks).warning,'');});
test('metrics classify every included record once and exclude review/utility marks',()=>{const m=c.PhoenixHomeMetrics;assert.equal(m.categoryFor('q-viper'),'exploration');assert.equal(m.categoryFor('gwent-start'),null);assert.equal(m.categoryFor('signpost-1'),null);const before=JSON.stringify(tasks);const b=m.derive(tasks,{},engine,engine.init());assert.equal(b.main.total,3);assert.equal(b.side.total,6);assert.equal(b.gwent.unavailable,true);assert.equal(JSON.stringify(tasks),before);});
class Element{
 constructor(tag,doc){this.tag=tag;this.doc=doc;this.children=[];this.attrs={};this.dataset={};this.hidden=false;this.listeners={};this.textContent='';const set=new Set();this.classList={add:(...xs)=>xs.forEach(x=>set.add(x)),remove:(...xs)=>xs.forEach(x=>set.delete(x)),contains:x=>set.has(x)};}
 setAttribute(k,v){this.attrs[k]=v;}getAttribute(k){return this.attrs[k];}append(...xs){this.children.push(...xs);}replaceChildren(...xs){this.children=xs;}querySelector(tag){for(const ch of this.children){if(ch.tag===tag||tag==='.'+ch.className)return ch;const found=ch.querySelector?.(tag);if(found)return found;}return null;}focus(){this.doc.activeElement=this;}addEventListener(k,f){(this.listeners[k]||=[]).push(f);}removeEventListener(){}remove(){}contains(el){return el===this||this.children.some(ch=>ch.contains?.(el));}fire(k,e={}){for(const f of this.listeners[k]||[])f(e);}
}
function med(opts={}){const d={listeners:{},addEventListener:Element.prototype.addEventListener,removeEventListener(){}};d.body=new Element('body',d);d.createElement=tag=>new Element(tag,d);let now=0,seq=0;const jobs=new Map();const w=load(['medallion.js'],{document:d,matchMedia:()=>({matches:false}),setTimeout(f,delay){jobs.set(++seq,{at:now+delay,f});return seq;},clearTimeout(id){jobs.delete(id);}});const api=w.createPhoenixMedallion(opts),core=api.element.children.at(-1);return{api,core,d,tick(ms){const end=now+ms;while(true){const next=[...jobs].filter(([,v])=>v.at<=end).sort((a,b)=>a[1].at-b[1].at)[0];if(!next)break;now=next[1].at;jobs.delete(next[0]);next[1].f();}now=end;}};}
test('separate quick Undo expires at three seconds while wolf remains navigation',()=>{const {api,core,tick}=med({onUndo:()=>true});api.signalUndoAvailable();assert.equal(api.isQuickUndoVisible(),true);assert.equal(api.quickUndo.classList.contains('fading'),true);assert.equal(api.getMode(),'nav');core.fire('click');assert.equal(api.isFanOpen(),true);tick(2999);assert.equal(api.isQuickUndoVisible(),true);tick(1);assert.equal(api.isQuickUndoVisible(),false);assert.equal(api.quickUndo.hidden,true);assert.equal(api.isFanOpen(),true);});
test('reduced motion retains the same three second lifetime',()=>{const {api,tick}=med({onUndo:()=>true,reducedMotion:true});api.signalUndoAvailable();tick(2999);assert.equal(api.isQuickUndoVisible(),true);tick(1);assert.equal(api.isQuickUndoVisible(),false);});
test('successful quick Undo invalidates stale warnings before presentation',()=>{let valid=true;const {api}=med({onUndo:()=>{valid=false;return true;}});api.signalUndoAvailable();api.enqueueWarning({text:'No longer true',isValid:()=>valid});api.quickUndo.onclick();assert.equal(api.getMode(),'nav');assert.equal(api.getQueueLength(),0);assert.equal(api.isQuickUndoVisible(),false);});
test('late durable Undo removes an already active stale warning',()=>{let valid=true;const {api}=med();api.enqueueWarning({text:'failed',isValid:()=>valid});valid=false;api.reconcileWarnings();assert.equal(api.getMode(),'nav');});
test('failed and throwing Undo recover warnings and announce failure',()=>{for(const onUndo of [()=>false,()=>{throw Error('failed');}]){const {api}=med({onUndo});api.signalUndoAvailable();api.enqueueWarning({text:'Keep me'});api.quickUndo.onclick();assert.equal(api.getActiveWarning().text,'Keep me');assert.match(api.element.querySelector('.medallion-status').textContent,/could not/);}});
test('no Undo without a callback or when availability throws',()=>{for(const opts of [{},{onUndo:()=>true,getUndoAvailable:()=>{throw Error();}}]){const {api}=med(opts);api.signalUndoAvailable();assert.equal(api.getMode(),'nav');}});
test('wolf gestures never invoke quick Undo',()=>{let calls=0;const {api,core}=med({onUndo:()=>{calls++;}});core.fire('pointerdown');api.signalUndoAvailable();core.fire('click');assert.equal(calls,0);assert.equal(api.isQuickUndoVisible(),true);});
test('open fan defers quick Undo until Escape closes navigation',()=>{const {api,core,d}=med({onUndo:()=>true});core.fire('click');api.signalUndoAvailable();assert.equal(api.isQuickUndoVisible(),false);for(const f of d.listeners.keydown)f({key:'Escape'});assert.equal(api.isQuickUndoVisible(),true);});
test('repeated progress restarts expiry and quick Undo executes once',()=>{let calls=0;const {api,tick}=med({onUndo:()=>{calls++;return true;}});api.signalUndoAvailable();tick(1500);api.signalUndoAvailable();tick(1000);assert.equal(api.isQuickUndoVisible(),true);api.quickUndo.onclick();api.quickUndo.onclick();assert.equal(calls,1);tick(2000);assert.equal(api.quickUndo.hidden,true);});
test('seeded history survives new acknowledgement and is copied to integration callback',()=>{let records;const {api}=med({history:[{id:'old',text:'Earlier',href:'#quest'}],onWarningHistory:r=>records=r});api.enqueueWarning({id:'new',text:'New',href:'#another'});api.acknowledgeWarning();assert.equal(records.length,2);assert.equal(api.getHistory()[0].id,'old');records.pop();assert.equal(api.getHistory().length,2);});

test('warning arriving during repeated Undo preserves the original FIFO head',()=>{const {api,tick}=med({onUndo:()=>true});api.enqueueWarning({id:'a',text:'A'});api.signalUndoAvailable();tick(500);api.signalUndoAvailable();api.enqueueWarning({id:'b',text:'B'});tick(3900);assert.equal(api.getActiveWarning().id,'a');});
test('browse registry survives row filtering and includes utility and shared task members',()=>{const x=load(['white-orchard.js','map-data.js']);const source=fs.readFileSync('app.js','utf8');vm.runInContext(source.slice(0,source.indexOf("  tasks['departure-review'].sections="))+'})();',x);const registry=x.PHOENIX_MAP_MEMBERSHIP;assert.equal(Object.isFrozen(registry),true);for(const h of x.PHOENIX_ROUTE.hubs){assert.equal(new Set(registry[h.id]).size,registry[h.id].length);}assert.ok(registry['hub-missing'].includes('q-viper'));assert.ok(Object.values(registry).flat().some(id=>id.startsWith('signpost-')));assert.ok(Object.values(registry).flat().some(id=>x.PHOENIX_ROUTE.tasks[id].type==='service'));});
test('cluster browse mode is excluded from serialized progress context',()=>{const source=fs.readFileSync('app.js','utf8');const body=source.slice(source.indexOf('  function persist() {'),source.indexOf('  function taskAnchor('));let saved;const x={state:{mapContext:{clusterMode:'progress',scope:'hub-missing'},progress:{schema:1}},key:'test',saveAvailable:true,saveBlocked:null,localStorage:{setItem(k,v){saved=JSON.parse(v);}},document:{querySelectorAll:()=>[]}};vm.runInNewContext(body+'persist();',x);assert.equal(saved.mapContext.clusterMode,undefined);assert.equal(saved.mapContext.scope,'hub-missing');assert.equal(saved.progress.schema,1);assert.equal(x.state.mapContext.clusterMode,'progress');});
test('warning mode retains separate navigation without acknowledging the warning',()=>{let route;const {api}=med({onNavigate:hash=>route=hash});api.enqueueWarning({id:'a',text:'A'});const nav=api.element.querySelector('.medallion-nav-toggle');assert.equal(nav.hidden,false);nav.onclick();assert.equal(api.isFanOpen(),true);api.element.querySelector('.medallion-fan').children[1].onclick();assert.equal(route,'#whiteorchard-tree');assert.equal(api.getActiveWarning().id,'a');assert.equal(api.getHistory().length,0);});
test('Undo navigation does not execute Undo or stop its timer',()=>{let undos=0;const {api,tick}=med({onUndo:()=>{undos++;return true;}});api.signalUndoAvailable();api.element.querySelector('.medallion-nav-toggle').onclick();assert.equal(api.isFanOpen(),true);tick(3900);assert.equal(api.getMode(),'nav');assert.equal(api.isFanOpen(),true);assert.equal(undos,0);});
test('wolf image and four illustrated navigation cards are present',()=>{const {api,core}=med();assert.equal(core.querySelector('img').src,'wolf-medallion-silver.png');const cards=api.element.querySelector('.medallion-fan').children;assert.equal(cards.length,4);for(const card of cards){assert.ok(card.querySelector('img').src);assert.ok(card.getAttribute('aria-label'));}});
test('wolf acknowledges all valid alerts and opens Warnings without an alert popup',()=>{let opened=0,acknowledged=0;const {api,core}=med({decorateNavigation:()=>({open(){},close(){},showWarnings(){opened++;}})});api.enqueueWarning({id:'a',text:'A',onAcknowledge(){acknowledged++;}});api.enqueueWarning({id:'b',text:'B',onAcknowledge(){acknowledged++;}});api.enqueueWarning({id:'stale',text:'Stale',isValid:()=>false});assert.equal(api.element.querySelector('.medallion-warning').hidden,true);core.fire('click');assert.equal(opened,1);assert.equal(acknowledged,2);assert.equal(api.getMode(),'nav');assert.equal(api.getHistory().length,2);assert.equal(api.getActiveWarning(),null);assert.equal(api.getQueueLength(),0);assert.equal(api.element.querySelector('.medallion-warning').hidden,true);});

test('configured command deck routes all five destinations without invoking Undo',()=>{let route,undos=0;const items=[['Home','#home','a'],['Regions','#regions','b'],['Field Reference','#field-reference','c'],['Progress','#progress','d'],['Constellation','#whiteorchard-constellation','e']];const {api,core}=med({navigationCards:items,onNavigate:r=>route=r,onUndo:()=>{undos++;}});const fan=api.element.querySelector('.medallion-fan');assert.equal(fan.children.length,5);for(let i=0;i<5;i++){core.fire('click');fan.children[i].onclick();assert.equal(route,items[i][1]);assert.equal(api.isFanOpen(),false);}assert.equal(undos,0);});
test('navigation decorator opens and releases its backdrop once per toggle',()=>{let opens=0,closes=0;const {core,api}=med({decorateNavigation:()=>({open(){opens++;},close(){closes++;}})});core.fire('click');assert.equal(opens,1);core.fire('click');assert.equal(closes,1);assert.equal(api.isFanOpen(),false);});
test('risk arriving during decorated navigation stays deferred until closure',()=>{const {api,core}=med({decorateNavigation:()=>({open(){},close(){}})});core.fire('click');api.enqueueWarning({id:'deferred',text:'risk'});assert.equal(api.getMode(),'nav');assert.equal(api.getActiveWarning(),null);core.fire('click');assert.equal(api.getActiveWarning().id,'deferred');assert.equal(api.getMode(),'warning');});

test('resolved departure messages are removed without clearing unrelated warnings',()=>{let saved;const {api}=med({onWarningHistory:list=>saved=list});api.seedHistory([{id:'departure-risk:q-missing',text:'Departure'},{id:'other',text:'Other'}]);api.enqueueWarning({id:'departure-risk:q-missing',text:'Departure'});api.enqueueWarning({id:'unrelated',text:'Keep'});api.removeWarnings(w=>w.id.startsWith('departure-risk:'));assert.equal(api.getActiveWarning().id,'unrelated');assert.equal(api.getHistory().length,1);assert.equal(api.getHistory()[0].id,'other');assert.equal(saved.length,1);});



test('warning history shortcut uses Warnings takeover rather than a second popup',()=>{let shown=0;const {api}=med({history:[{text:'Earlier'}],decorateNavigation:()=>({open(){},close(){},showWarnings(){shown++;}})});api.showHistory();assert.equal(shown,1);assert.equal(api.isFanOpen(),true);assert.equal(api.element.querySelector('.medallion-history').hidden,true);});
